import math
import subprocess
import sys

PY = sys.executable


def run(*args):
    return subprocess.run([PY, "bayes.py", *args], capture_output=True, text=True)


def parse_prob(stdout):
    return float(stdout.strip().split(":")[1])


def test_pinned_example():
    r = run("--pretest", "0.30", "--lr", "8.0")
    assert r.returncode == 0
    # exact expected: 0.30 -> odds 3/7, *8 = 24/7, prob = 24/31 = 0.7742
    assert abs(parse_prob(r.stdout) - 0.774) < 5e-4
    assert r.stdout == "post-test probability: 0.774\n"


def test_chained_lr_equals_single():
    chained = run("--pretest", "0.25", "--lr", "2", "--lr", "3")
    single = run("--pretest", "0.25", "--lr", "6")
    assert chained.returncode == single.returncode == 0
    assert math.isclose(
        parse_prob(chained.stdout), parse_prob(single.stdout), rel_tol=0, abs_tol=1e-9
    )


def test_lr_one_unchanged():
    r = run("--pretest", "0.42", "--lr", "1.0")
    assert r.returncode == 0
    assert math.isclose(parse_prob(r.stdout), 0.42, abs_tol=5e-4)


def test_tiny_pretest():
    r = run("--pretest", "0.001", "--lr", "10")
    assert r.returncode == 0
    assert abs(parse_prob(r.stdout) - 0.00991) < 1e-5


def test_guard_pretest_out_of_range():
    for bad in ("0", "1", "-0.5", "1.5"):
        r = run("--pretest", bad, "--lr", "2")
        assert r.returncode == 2
        assert r.stderr.strip()
        assert not r.stdout


def test_guard_nonpositive_lr():
    for bad in ("0", "-3"):
        r = run("--pretest", "0.3", "--lr", bad)
        assert r.returncode == 2
        assert r.stderr.strip()
        assert not r.stdout

